with a as(select * from public.authors where open_library_id=any(array['OL124895A','OL439216A','OL12303130A','OL496967A','OL46833A','OL579866A','OL585546A','OL2101579A','OL45664A','OL29542A','OL8042570A','OL2644956A']::text[]) or id=any(array[639,2613,2172]::bigint[])) select jsonb_build_object('checked_at',clock_timestamp(),'authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'isbn_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789051080933','9789064031960','9789070066741','9789085081449','9789028302808']::text[])),'source_work_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where open_library_id=any(array['OL1237227W','OL3477651W','OL15056324W','OL15895132W','OL20915078W']::text[])),'title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','works','row',to_jsonb(t))),'[]') from public.works t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['aphrodite','aphroditeancientmanners','afrodite','hitchcock','hitchcocktruffaut','dezwaardvis','theartofrawlivingfood','rawfoodalslevenskunst','thetravellerinblack','reizigerindechaos']::text[])),'edition_title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','editions','row',to_jsonb(t))),'[]') from public.editions t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['aphrodite','aphroditeancientmanners','afrodite','hitchcock','hitchcocktruffaut','dezwaardvis','theartofrawlivingfood','rawfoodalslevenskunst','thetravellerinblack','reizigerindechaos']::text[])),'reserved_test_ranges',jsonb_build_object('works',(select count(*) from public.works where id between 987164001 and 987164999),'editions',(select count(*) from public.editions where id between 987264001 and 987264999),'authors',(select count(*) from public.authors where id between 987364001 and 987364999))) as preflight;
